insert into mirror.housing_options (key, sort, title, summary, description)
values
  ('independent', 10, 'Living on my own', 'Your own apartment or house, rented or owned, run your way.', '{"what":"You hold the lease or own the home. You decide who lives with you, when you come and go, and how you run your day.","support":"No support comes with the home itself. Family, friends or community services can still help when you want them.","who":"Anyone who wants to run their own home, with or without help from outside.","pay":"Rent or a mortgage, plus utilities. Rent help such as a housing choice voucher can lower what you pay.","ask":["What is the full monthly cost, with utilities?","Is it close to the bus, stores and the people I count on?","Can I make changes I need, like grab bars?"]}'::jsonb),
  ('supported_independent', 20, 'My own place, with support that comes to me', 'Your own home, with help that visits you there.', '{"what":"You live in your own place. Help comes to you: for example a home care worker, a nurse visit, meals, or someone who checks in.","support":"As much or as little as you choose and qualify for, from a few hours a month to help every day.","who":"People who want to stay in their own home and would like help with some everyday tasks.","pay":"Rent as usual. In Wisconsin, programs such as Family Care or IRIS may pay for support at home for people who qualify.","ask":["Which tasks would I like help with?","Who would come, and how often?","Can I choose or change my helper?"]}'::jsonb),
  ('assisted', 30, 'Assisted living', 'A home with your own room or apartment, where help is there every day.', '{"what":"You live in a place where staff help with things like meals, medicine and personal care. In Wisconsin this includes adult family homes, community-based residential facilities (CBRFs) and residential care apartment complexes (RCACs).","support":"Staff are on site; how much they help depends on the place and on what you need.","who":"People who would like daily help close by. It is one option among several, never the only one, and it is your choice.","pay":"Usually a monthly fee for room, board and care. Medicaid programs may pay the care part for people who qualify.","ask":["Will I have my own room and my own bathroom?","What does the monthly fee include, and what costs extra?","Can I keep my routines, my visitors and my things?"]}'::jsonb),
  ('skilled_nursing', 40, 'Nursing home (skilled nursing care)', 'Nursing care around the clock, for a short stay or longer.', '{"what":"Nurses and aides are on duty day and night. Many people stay for a short time, for example to recover after a hospital stay, then go home.","support":"Medical and personal care at any hour.","who":"Usually people whose doctor or care team says they need nursing care every day. You still have a say in where you go and for how long.","pay":"Medicare may pay for a short stay after a hospital visit; Medicaid may pay for a longer stay for people who qualify.","ask":["Is this for a short stay or longer?","What is the plan to go home?","Who can I talk to if I want to leave?"]}'::jsonb),
  ('accessible', 50, 'Accessible housing', 'A home built or changed to fit your body and your needs.', '{"what":"For example no steps at the door, wide doorways, a roll-in shower, grab bars, or flashing smoke alarms. It can be your own place or any other kind of housing.","support":"The home itself is the support. Help from people can be added, as in the other options.","who":"Anyone who would be safer or freer in a home without barriers.","pay":"Like any rent. Landlords may have to allow reasonable changes you ask for; some programs help pay for changes.","ask":["Which features do I need, and which would be nice?","Is the building and the way in accessible, not only the unit?","Can changes be made if I need more later?"]}'::jsonb),
  ('permanent_supportive', 60, 'Permanent supportive housing', 'Your own lease, with rent help and support services, and no time limit.', '{"what":"A home of your own with a lease, plus a case manager or support staff you can work with. You can stay as long as you follow the lease.","support":"Support services you can work with. In Housing First programs, using them is not a condition of keeping your home; ask each program.","who":"Often people who have been without a home for a long time and live with a disability. Entry is usually through a referral or a waiting list.","pay":"Usually about 30 percent of your income goes to rent; the program pays the rest.","ask":["How do I get on the list, and who refers me?","What support is offered, and is it required?","How long is the wait?"]}'::jsonb),
  ('other_specialized', 70, 'Other specialized housing', 'Homes for a particular group or purpose.', '{"what":"For example senior apartments, recovery housing, shared housing with roommates, housing for young adults, or for families leaving violence.","support":"Depends on the place: from none to a lot.","who":"People for whom one of these fits what they want right now.","pay":"Depends on the program; many charge rent based on income.","ask":["What are the house rules?","How long can I stay?","What happens if my needs change?"]}'::jsonb)
on conflict (key) do nothing;
